function combinationSumImpl(candidates, target) {
  candidates.sort((a,b) => a-b);
  const result = [];
  function backtrack(start, rem, path) {
    if (rem === 0) { result.push([...path]); return; }
    for (let i = start; i < candidates.length; i++) {
      if (candidates[i] > rem) break;
      path.push(candidates[i]); backtrack(i, rem-candidates[i], path); path.pop();
    }
  }
  backtrack(0, target, []);
  return result;
}

