function combinationSum3Impl(k, n) {
  const result = [];
  function backtrack(start, rem, path) {
    if (path.length === k && rem === 0) { result.push([...path]); return; }
    if (path.length === k || rem <= 0) return;
    for (let i = start; i <= 9; i++) {
      path.push(i); backtrack(i+1, rem-i, path); path.pop();
    }
  }
  backtrack(1, n, []);
  return result;
}

