function letterCombinationsImpl(digits) {
  if (!digits.length) return [];
  const pm = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'};
  const result = [];
  function backtrack(index, path) {
    if (index === digits.length) { result.push(path.join('')); return; }
    for (const letter of pm[digits[index]]) {
      path.push(letter); backtrack(index+1, path); path.pop();
    }
  }
  backtrack(0, []);
  return result;
}

function letterCombinationsIter(digits) {
  if (!digits.length) return [];
  const pm = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'};
  let result = [''];
  for (const digit of digits) {
    const next = [];
    for (const combo of result)
      for (const letter of pm[digit])
        next.push(combo + letter);
    result = next;
  }
  return result;
}

